    correctKey: 'B',
    explanation: '標準管理規約第24条第1項は、区分所有者は、その共有する共用部分等について、管理組合が火災保険その他の損害保険の契約を締結することにつき、あらかじめ同意したものとみなす旨を定める。これにより、区分所有者全員の個別の同意を都度得ることなく、管理組合として円滑に共用部分の損害保険契約を締結・更新することができる。理事長は、この保険契約に基づく保険金請求・受領について区分所有者を代理する。\n\n【図解】共用部分の損害保険\n　項目｜内容｜根拠\n　契約締結への同意｜区分所有者はあらかじめ同意したものとみなす｜規約24条1項\n　保険金の請求と受領｜理事長が区分所有者を代理する｜法26条2項\n　法律上の位置づけ｜共用部分の管理に関する事項とみなす｜法18条4項\n　⇒ 個別の同意を都度得る必要がないため、契約や更新の手続が円滑に進む\n　⚠ 保険加入自体は義務ではない。加入するかどうかは集会の決議による。',
