    correctKey: 'C',
    explanation: '標準管理規約第25条第1項は、区分所有者は、共用部分等の管理に要する経費に充てるため、規約で定めるところにより、管理費及び修繕積立金を管理組合に納入しなければならないと定める。管理費・修繕積立金の負担割合は、原則として共用部分の共有持分割合（専有部分の床面積割合が基礎）によることが多いが、規約で別段の定め（住戸タイプ別の傾斜配分等）をすることもできる。\n\n【図解】管理費等の負担割合\n　項目｜原則｜例外\n　負担割合の基準｜共用部分の共有持分割合｜規約で別段の定めが可能\n　共有持分の基準｜専有部分の床面積の割合｜住戸タイプ別の傾斜配分も可\n　納入の義務者｜区分所有者｜賃借人は組合に対し義務を負わない\n　⇒ 負担割合そのものを変えるには規約の変更が必要\n　⚠ 「使用していなければ負担しなくてよい」は誤り。負担は所有に伴う義務。',
