    correctKey: 'D',
    explanation: '標準管理規約は、区分所有法6条の共同の利益に反する行為の禁止と、これに対する57条の行為の停止等の請求、58条の使用禁止請求、59条の競売請求、60条の占有者に対する引渡し請求という法律上の枠組みを確認的に規定している。したがって規約が独自の制度を創設しているわけではなく、決議要件（57条の訴えは普通決議、58条から60条までは各4分の3以上と弁明の機会の付与）も法律に従う。あわせて標準管理規約は、これらの訴訟に至る前の初期対応として、理事会の決議を経て理事長が違反者に対し是正のための勧告・指示・警告を行うことができる旨の規定例を示している。\n\n【図解】規約と区分所有法の役割分担\n　段階｜根拠｜要件\n　勧告・指示・警告｜標準管理規約の規定例｜理事会の決議\n　行為の停止等の請求の訴え｜法57条｜総会の普通決議\n　使用禁止・競売・引渡しの請求｜法58条から60条｜各4分の3以上と弁明の機会\n　⇒ 規約は法の枠組みを前提に、初期対応の手段を上乗せしている\n　⚠ 「規約で決議要件を理事会限りに変更できる」は誤り。法定要件は動かせない。',
