    correctKey: 'C',
    explanation: '駐車場使用細則には、駐車場の使用者の選定方法（抽選、申込み順、輪番制など）、使用期間、使用料の額および改定の手続、車両の変更や入替えの手続、使用者の遵守事項、使用料の不払いや無断駐車があった場合の措置といった、駐車場の適正な利用と管理に必要な事項が定められる。使用細則は規約の委任に基づく下位規範であるから、規約に反する内容を定めることはできず、制定・変更は総会の普通決議による。区分所有者の職業・学歴・年収といった個人のプライバシーに関する情報は、駐車場の管理に必要な事項ではないから、細則で定めるべきものではない。\n\n【図解】駐車場使用細則に定める事項\n　区分｜具体的な内容｜目的\n　使用者の選定｜抽選・申込み順・輪番制｜公平な配分の実現\n　料金と期間｜使用料の額・改定手続・使用期間｜収入の確保と定期的な入替え\n　遵守事項と措置｜保険加入・違反時の使用停止｜適正な利用の確保\n　⇒ 細則は規約の委任の範囲内で定める必要がある\n　⚠ 年収や学歴などのプライバシー情報を細則の事項とすることは想定されていない。',
