    correctKey: 'A',
    explanation: '消防法17条の3の3は、消防用設備等について定期に点検し、その結果を消防長または消防署長に報告することを関係者に義務づけている。共同住宅では機器点検を6か月ごと、総合点検を1年ごとに行い、非特定防火対象物である共同住宅は3年に1回報告する。自動火災報知設備の感知器は専有部分内にも設置されているため、点検には住戸への立入りが不可欠であるが、不在や協力の拒否によって未実施となる住戸が生じやすい。そこで、事前通知の方法、立会いの調整、再点検の実施、協力義務などを規約や細則に定めておくことが実務上きわめて重要となる。\n\n【図解】消防用設備等の点検\n　種別｜周期｜内容\n　機器点検｜6か月ごと｜外観と機能の確認\n　総合点検｜1年ごと｜作動状況の総合的な確認\n　消防機関への報告｜共同住宅は3年に1回｜点検結果の報告\n　⇒ 専有部分内の感知器も点検の対象となる\n　⚠ 「専有部分内は点検できない」は誤り。立入りの協力を細則で確保する。',
