    correctKey: 'B',
    explanation: '標準管理規約が定める専有部分の貸与に関する届出義務（第31条）は、賃借人の氏名・連絡先等の情報を管理組合が把握するための仕組みであり、これは暴力団員排除条項（貸与契約への確約条項の組込み等）の実効性を確保する上でも重要な役割を果たす。両者は相互に関連し合いながら、マンションの安全な居住環境の維持に資するものである。\n\n【図解】届出義務と暴力団排除の連動\n　仕組み｜内容｜効果\n　貸与の届出｜賃借人の氏名・連絡先を管理組合に届け出る｜占有者の把握\n　契約への確約条項｜暴力団員でない旨を確約させる｜違反時の解除原因となる\n　解除権の代理行使｜管理組合が解除を代理できる定め｜実効的な排除が可能\n　⇒ 情報の把握と契約上の手当てが両輪となる\n　⚠ 届出がなされないと、排除条項の実効性は大きく低下する。',
