    correctKey: 'A',
    explanation: '標準管理規約47条1項は、総会の会議は議決権総数の半数以上を有する組合員が出席しなければ開くことができないと定める。定足数を満たさない場合には総会そのものを開くことができず、決議をしても効力を生じない。定足数の算定にあたっては、会場に現実に出席した組合員だけでなく、議決権行使書によって議決権を行使した組合員および委任状により代理人を出席させた組合員も出席組合員として算入される。WEB会議システム等を用いて出席した組合員も同様である。なお定足数は区分所有法に定めがなく、規約で定めるべき事項である。\n\n【図解】定足数に算入されるもの\n　出席の形態｜定足数への算入｜賛否への算入\n　会場への現実の出席｜算入される｜算入される\n　議決権行使書による行使｜算入される｜算入される\n　委任状による代理出席｜算入される｜代理人の判断による\n　⇒ 定足数を欠く総会では決議をすることができない\n　⚠ 「書面や代理人による行使者は出席として扱われない」は誤り。',
