    correctKey: 'B',
    explanation: '標準管理規約42条4項は、理事長が必要と認める場合には理事会の決議を経て、いつでも臨時総会を招集することができると定める。招集手続は通常総会と同じであり、少なくとも会議を開く日の2週間前までに、会議の日時・場所・目的を示して通知を発しなければならない（43条1項）。また組合員総数の5分の1以上および議決権総数の5分の1以上に当たる組合員の同意を得て会議の目的を示した請求があったときは、理事長は2週間以内に、請求の日から4週間以内の日を会日とする臨時総会の招集通知を発しなければならない（44条1項）。監事も不正の事実等があると認めるときは臨時総会を招集できる。\n\n【図解】臨時総会の招集権者\n　招集する者｜要件｜根拠\n　理事長｜理事会の決議を経る｜規約42条4項\n　組合員｜組合員数と議決権の各5分の1以上の同意｜規約44条1項\n　監事｜不正の事実等があると認めるとき｜規約41条\n　⇒ 招集手続は通常総会と同じく2週間前までの通知が必要\n　⚠ 「臨時総会は招集通知が不要」は誤り。手続は通常総会と変わらない。',
