    correctKey: 'C',
    explanation: '区分所有法45条1項は、規約により集会において決議すべきものとされた事項について、区分所有者全員の承諾があるときは、書面または電磁的方法による決議ができると定める。また同条2項は、規約により集会において決議すべきものとされた事項について区分所有者全員の書面または電磁的方法による合意があったときは、書面等による決議があったものとみなすとする。いずれも全員の承諾または合意が要件であるから、対象は普通決議事項に限られず特別多数決議事項にも及ぶ。書面等による決議は集会の決議と同一の効力を有する（同条3項）。\n\n【図解】書面等による決議\n　方式｜要件｜効果\n　書面等による決議（法45条1項）｜区分所有者全員の承諾｜集会を開かずに決議できる\n　みなし決議（法45条2項）｜区分所有者全員の合意｜決議があったものとみなす\n　⇒ 全員一致が前提なので、普通決議事項も特別多数決議事項も対象になる\n　⚠ 「過半数の合意で書面決議ができる」は誤り。全員の承諾または合意が必要。',
