    explanation: '標準管理規約における専有部分の範囲（天井・床・壁は躯体部分を除く仕上げ部分のみ）を踏まえると、専有部分内で行われるリフォーム工事であっても、躯体（柱・梁・耐力壁等の共用部分）に直接影響を及ぼす工事（構造壁の撤去等）は、専有部分の自由な使用の範囲を超え、共用部分の変更に関する手続（理事会の承認、場合により総会の決議）を要することがある。\n\n【図解】躯体と仕上げの区分\n　部位｜専有部分となる範囲｜共用部分となる範囲\n　天井・床・壁｜内側の仕上げ部分｜躯体のコンクリート部分\n　柱・梁・耐力壁｜該当しない｜すべて共用部分\n　室内の間仕切り壁｜専有部分｜構造耐力上主要な壁は除く\n　⇒ 躯体に手を加える工事は共用部分の変更の問題となる\n　⚠ 「室内の壁はすべて自由に撤去できる」は誤り。耐力壁は共用部分。',
