    correctKey: 'A',
    explanation: '標準管理規約は、区分所有法第33条の規約の保管・閲覧に関する規律を踏まえ、理事長は、規約、総会議事録、会計帳簿等の重要書類について、組合員又は利害関係人からの請求があったときは、正当な理由がある場合を除いて、閲覧させなければならない旨を定めている。これは、マンションの購入を検討する者を含む利害関係人にとって、重要な情報収集の手段となる。\n\n【図解】閲覧請求の対象と請求できる者\n　書類｜請求できる者｜根拠\n　規約｜利害関係人｜法33条2項\n　総会・理事会の議事録｜組合員および利害関係人｜法33条2項と規約\n　会計帳簿・組合員名簿｜組合員および利害関係人｜規約\n　⇒ 正当な理由がある場合を除いて拒むことができない\n　⚠ 「購入を検討している者は利害関係人にあたらない」は誤り。閲覧を請求できる。',
