    correctKey: 'C',
    explanation: '長期修繕計画は、建築資材費や工事費の変動、実際の劣化状況、計画修繕の実施状況を踏まえて5年程度ごとに見直すことが望ましいとされる。見直しの結果、計画期間内に必要となる修繕費に対して積立金が不足すると見込まれる場合には、修繕積立金の額の改定（値上げ）、一時金の徴収、金融機関からの借入れといった対応を検討することが管理組合の重要な業務となる。修繕積立金の額および賦課徴収方法は総会の決議事項であるから、値上げは総会の普通決議で決定でき、区分所有者全員の同意も規約の変更も必要ない。\n\n【図解】積立不足への対応\n　対応策｜必要な決議｜特徴\n　修繕積立金の増額改定｜総会の普通決議｜恒久的に収支を改善する\n　一時金の徴収｜総会の普通決議｜短期間で資金を確保できる\n　金融機関からの借入れ｜総会の普通決議｜将来の積立金で返済する\n　⇒ 長期修繕計画の見直しと資金計画はセットで検討する\n　⚠ 「値上げには全員の同意が必要」は誤り。総会の普通決議で足りる。',
    difficulty: 'standard',
