    correctKey: 'C',
    explanation: '総会の招集通知には「会議の目的たる事項」（議題）を示す必要がある（区分所有法第35条第1項）。この議題の範囲内で、より具体的な提案内容（議案）が総会に提出され、決議の対象となる。実務上は、招集通知に議案の詳細（提案理由書等）を添付し、組合員が事前に内容を検討できるようにすることが望ましいとされている。\n\n【図解】議題と議案の関係\n　用語｜意味｜通知の要否\n　議題（会議の目的たる事項）｜審議する事柄の枠組み｜必ず通知する（法35条1項）\n　議案｜議題の枠内の具体的な提案｜特別決議事項は要領の通知が必要\n　動議｜議案の細部を修正する提案｜議題の範囲内なら提出できる\n　⇒ 通知した議題の範囲を超える決議をすることはできない\n　⚠ 特別多数決議事項では議案の要領の通知が必要（法35条5項）。',
