    correctKey: 'A',
    explanation: '標準管理規約41条1項は、監事は管理組合の業務の執行および財産の状況を監査し、その結果を総会に報告しなければならないと定める。会計監査は毎会計年度終了後、収支決算案が理事会で確定して通常総会に提出されるまでの間に実施するのが実務上の流れであり、監事は会計帳簿、預金通帳、領収書等の証憑と決算書類を突き合わせ、残高と計上額の一致を確認する。監査の結果は監査報告書にまとめられ、通常総会で報告される。監査は毎年度実施すべきものであり、数年分をまとめて行えば足りるものではない。理事長が自ら監査することは独立性を欠くため認められない。\n\n【図解】会計監査の流れ\n　段階｜担当｜内容\n　決算案の作成｜会計担当理事｜収支報告書と貸借対照表の作成\n　会計監査｜監事｜帳簿・通帳・証憑と決算書類の突合\n　監査報告｜監事｜通常総会で監査の結果を報告\n　⇒ 監査は毎会計年度終了後、決算承認に先立って行う\n　⚠ 「監査は数年に1回でよい」は誤り。毎会計年度実施する。',
    difficulty: 'standard',
