    correctKey: 'B',
    explanation: '共用部分の変更が「その形状又は効用の著しい変更を伴わないもの」（軽微変更）に該当するか否かは、区分所有法上、明確な数値基準が定められているわけではなく、工事の規模、費用、建物の外観・機能への影響の程度等を総合的に考慮して個別に判断されるべき事項とされている。判断に迷う事案では、専門家（マンション管理士、弁護士等）への相談が実務上有用である。\n\n【図解】重大変更か軽微変更かの判断要素\n　要素｜重大変更に傾く場合｜軽微変更に傾く場合\n　工事の規模と費用｜建物全体に及び費用が多額｜部分的で費用も限定的\n　外観や機能への影響｜外観や用途が大きく変わる｜従前の性能を回復する程度\n　原状回復の可否｜元に戻すことが困難｜容易に復元できる\n　⇒ 明確な数値基準はなく、総合的に個別判断する\n　⚠ 「費用が一定額を超えれば重大変更」といった基準は法令には存在しない。',
    difficulty: 'advanced',
