    correctKey: 'A',
    explanation: '宅配ボックスの新設は、エントランス等の共用部分への設備の追加であり、共用部分の変更に該当する。工事の規模・費用や建物の効用への影響の程度に応じて、軽微な変更として普通決議で足りる場合もあれば、著しい変更として特別決議（各4分の3以上）を要する場合もある。近年の宅配需要の増加を踏まえ、多くの管理組合で検討される設備投資の一例である。\n\n【図解】宅配ボックス新設の決議\n　態様｜変更の程度｜決議要件\n　既存スペースへの小規模な設置｜軽微な変更｜普通決議\n　エントランスの改造を伴う設置｜著しい変更に当たりうる｜各4分の3以上\n　費用の財源｜修繕積立金または管理費｜総会で財源も決議する\n　⇒ 工事の規模と建物の効用への影響で決議要件が決まる\n　⚠ 一律に普通決議でよいとする肢は誤り。態様により異なる。',
    difficulty: 'standard',
