    correctKey: 'B',
    explanation: '専有部分内の給排水管からの漏水事故は、マンションにおいて頻繁に生じるトラブルの一つである。その責任の所在を判断するには、漏水の原因が専ら専有部分内の設備（枝管等、専有部分に属する部分）にあるのか、共用部分（本管等）にあるのかを確認する必要があり、この点で共用部分・専有部分の区分（標準管理規約第7条等）の理解が重要となる。管理組合は、原因調査への協力（立入りの調整等）を通じて、円滑な解決を支援する役割を担うことがある。\n\n【図解】漏水の原因と責任の切分け\n　原因箇所｜責任を負う者｜費用の手当て\n　専有部分内の枝管｜当該住戸の区分所有者｜個人賠償責任保険など\n　共用の縦管｜管理組合（区分所有者全員）｜共用部分の保険など\n　原因が特定できない場合｜共用部分の瑕疵と推定される｜法9条\n　⇒ まず共用部分と専有部分の区分を確認することが出発点となる\n　⚠ 原因調査のための立入りを正当な理由なく拒むことはできない。',
    difficulty: 'advanced',
