    correctKey: 'D',
    explanation: '民法第717条は、土地の工作物の設置又は保存に瑕疵があることによって他人に損害を生じたときは、その工作物の占有者が損害賠償責任を負い、占有者が損害の防止に必要な注意をしたときは、所有者が責任を負う旨を定める（工作物責任）。共用部分（エントランス、外壁、手すり等）はこの「土地の工作物」に該当し得るため、その設置又は保存に瑕疵があり事故が生じた場合、管理組合や区分所有者の責任が問題となり得る。管理組合が締結する損害保険（施設賠償責任保険等）は、こうしたリスクへの備えとして重要な意義を持つ。\n\n【図解】共用部分の瑕疵による事故\n　主体｜責任の性質｜備え\n　占有者｜必要な注意をしたと証明すれば免責｜施設賠償責任保険\n　所有者である区分所有者全員｜無過失責任｜同保険と適切な点検\n　瑕疵の所在｜共用部分にあるものと推定される｜法9条\n　⇒ 定期的な点検と記録の保存が最大の防御となる\n　⚠ 管理会社に委託していても、区分所有者の対外的な責任は消えない。',
