    explanation: '老朽化が進んだマンションにおいては、修繕を重ねながら維持していくか、建替え（区分所有法上の建替え決議）を行うか、マンション敷地売却（円滑化法上の制度）を選択するかなど、将来に向けた重要な選択を迫られる場面が生じ得る。こうした重大な意思決定には長期間にわたる合意形成が必要となるため、老朽化の兆候が現れる前の早い段階から、区分所有者間で将来の方向性について検討・協議を進めていくことが望ましいとされている。マンション管理士は、こうしたプロセスにおける専門的な助言者としての役割が期待される。\n\n【図解】老朽化マンションの選択肢\n　選択肢｜決議要件｜前提となる条件\n　修繕を重ねて維持する｜普通決議｜資金計画と長期修繕計画の整備\n　建替え｜区分所有者と議決権の各5分の4以上｜合意形成と資金負担の見通し\n　マンション敷地売却｜各5分の4以上｜特定要除却認定を受けること\n　⇒ 合意形成には長期間を要するため早い段階からの検討が望ましい\n　⚠ 決議の直前に検討を始めても、5分の4の賛成を得ることは難しい。',
